"""内容准确性全轨迹评分 prompt。

将完整 ReAct 轨迹（含工具调用+观测结果+最终回答）发给 judge，
专项评估最终回答中的产品信息是否真实、有据可查。

与 gsb_absolute.py 的差异：
  - 评分对象扩展为整条 ReAct 轨迹（含工具查询和观测），而非仅最终答案
  - 专注 accuracy 单一维度（二值 0/1 打分），区分准确与不准确两类
  - judge 可对照工具实际返回的产品数据判断答案是否捏造/混淆

脱敏：同 gsb_pairwise.py，对手机号/身份证/银行卡号做替换。
"""

from __future__ import annotations

import re
from typing import Any, Dict, List

# ── 敏感信息正则（同 gsb_pairwise.py）─────────────────────────────────────────
_RE_ID_CARD = re.compile(r"(?<!\d)\d{17}[\dXx](?!\d)|(?<!\d)\d{15}(?!\d)")
_RE_PHONE = re.compile(r"(?<!\d)1[3-9]\d{9}(?!\d)")
_RE_BANK_CARD = re.compile(
    r"(?<!\d)\d{4}(?:[ \-]\d{4}){2,3}(?:[ \-]\d{1,4})?(?!\d)"
    r"|(?<!\d)62\d{14,17}(?!\d)"
)


def _mask_sensitive(text: str) -> str:
    text = _RE_ID_CARD.sub("[IDCARD]", text)
    text = _RE_PHONE.sub("[PHONE]", text)
    text = _RE_BANK_CARD.sub("[BANKCARD]", text)
    return text


# ── 知识库工具名单 ──────────────────────────────────────────────────────────────
# 这些工具的 observation 直接来自知识库，作为 judge 评估准确性的参考依据。
# 轨迹中若未调用任何这些工具，则跳过 accuracy 评估（reward 返回中性值）。
KNOWLEDGE_TOOL_NAMES: frozenset = frozenset({
    "search_product_clause",     # 指定产品 skuid 的条款/材料 chunk 检索
    "search_product_qa",         # 指定产品 skuid 的产品维度 QA 检索
    "run_product_recommend",     # SOP 问卷式产品推荐（内部调用知识检索）
    "run_contextual_recommend",  # 情境推荐（内部调用知识检索）
    "run_premium_calc",          # 保费试算（基于产品费率数据）
})


def _diff_obs_messages(
    cur_messages: List[Dict[str, Any]],
    next_messages: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """提取相邻步骤间的工具观测消息（next_messages 比 cur_messages 多出来的部分，去掉首条 assistant）。

    与 trajectory.builder._diff_observation_messages 逻辑一致，此处内联以避免循环依赖。
    """
    n = len(cur_messages)
    tail: List[Dict[str, Any]] = list(next_messages[n:])
    while tail and (tail[0].get("role") if isinstance(tail[0], dict) else "") == "assistant":
        tail = tail[1:]
    return tail


def _step_calls_knowledge_tool(step: Any) -> bool:
    """判断某步是否调用了知识库工具（含并行调用）。"""
    action_name = (getattr(step, "action_name", "") or "").strip()
    if action_name in KNOWLEDGE_TOOL_NAMES:
        return True
    if action_name == "parallel":
        parsed = getattr(step, "parsed_action", None)
        if isinstance(parsed, dict):
            calls = parsed.get("calls") or []
            return any(
                isinstance(c, dict) and (c.get("name") or "") in KNOWLEDGE_TOOL_NAMES
                for c in calls
            )
    return False


def extract_knowledge_from_steps(steps: List[Any], max_chars: int = 8000) -> str:
    """从轨迹 steps 中提取知识库工具的 observation，合并返回。

    遍历每步，当该步调用了 KNOWLEDGE_TOOL_NAMES 中的工具时，提取其工具返回内容
    （通过相邻步骤 messages 的 diff 获取 observation）。

    Returns:
        合并后的知识文本；若轨迹中未调用任何知识库工具则返回空字符串。
    """
    if not steps:
        return ""

    parts: List[str] = []
    for i, step in enumerate(steps):
        if i + 1 >= len(steps):
            break  # 最后一步无下一步，无法 diff observation
        if not _step_calls_knowledge_tool(step):
            continue

        cur_msgs: List[Dict[str, Any]] = list(getattr(step, "messages", None) or [])
        next_msgs: List[Dict[str, Any]] = list(getattr(steps[i + 1], "messages", None) or [])
        obs_msgs = _diff_obs_messages(cur_msgs, next_msgs)

        obs_text = "\n".join(
            (msg.get("content") or "").strip()
            for msg in obs_msgs
            if isinstance(msg, dict)
            and (msg.get("content") or "").strip()
            and msg.get("role") != "system"
        ).strip()

        if obs_text:
            parts.append(obs_text)

    if not parts:
        return ""

    full = "\n\n---\n\n".join(parts)
    if len(full) > max_chars:
        full = "...[知识内容过长，保留末尾]\n\n" + full[-max_chars:]
    return full


# ── Judge Prompt ───────────────────────────────────────────────────────────────

ACCURACY_JUDGE_SYSTEM_PROMPT = """\
你是一位经验丰富的保险 AI 顾问系统准确性评测专家，具备保险产品知识储备。
你将看到一个 AI 系统处理保险咨询的完整推理轨迹（包括工具调用和返回结果）以及最终回答。
你的任务是评估最终回答中的内容准确性。
"""

